// th14_s3_b2 — TH14 v1.00b st03bs.ecl / BossCard1 (spell ID 28), entry source lines 323-452.
// Dependencies: BossCard1_at 454-492, BossCard1_at_l 494-561, BossCard1_shadow 563-574.
// Source clock: timerReset() at :326 starts the 2400-frame interrupt; this card starts the
// source timeline at the first execution of boss_main (card frame ~122, after OPENING_BUFFER).
// At source frame 2400 the timeout path clears the field (Boss2 boundary: killAllAsync/etClear 640),
// which is reproduced by the stop block at the end of boss_main.

const TIME_LIMIT: int = 2884;   // 120 opening + 2760 window (2400 attack + tail budget)
const OPENING_BUFFER: int = 120;

// ---------------------------------------------------------------------------
// Parent bullet: source type 18 BIG_BALL color 3, born at speed 0 (last etSpeed before
// etOn is 0,0), etDist 32 handled by the caller, then EX record chain:
//   ANIM 1 / BRIGHT 1 / SPEEDUP 1  -> birth presentation, omitted per policy
//   WAIT 10                        -> @10 add_speed(0)
//   ANGLE_ACCEL a=50 r=0.02|0.022 s=F0(+-2deg/frame) -> set_ang_vel + set_accel for 50 frames
//   SHOOT + SHOOT_DATA c=1         -> split task fires children, parent deleted
// ---------------------------------------------------------------------------
xformdef FANG_PARENT(omega: angle, accel: fx) {
    @10 add_speed(0fx);
    set_ang_vel(omega);
    @50 set_accel(accel);
    stop_fx();
    set_life(1);
}

// BossCard1_at SHOOT: aim mode 8, angle = parent angle + U_signed*5deg, speed = parent + U*1.8.
// Paired SHOOT_DATA (type 5 color 2, delete parent) -> FANG_PARENT set_life(1).
// Child copies parent EX from record 10 (ANIM/PLAYSOUND/BRIGHT): only the ANIM birth
// displacement position -= 4*velocity is retained.
async sub fang_split_one() {
    wait(59);                                   // task starts at age 1; split at parent age 60
    var ra: int = rand(65536);
    var off: int = (ra - 32768) * 910 / 32768;  // 5deg = 910 BAM
    var a: angle = $self_angle + (off as angle);
    var rv: int = rand(65536);
    var u: fx = (rv - 32768) as fx / 65536 + 0.5fx;
    var spd: fx = $self_speed + u * 1.8fx;
    var bx: fx = $self_x - 4fx * spd * cos(a);
    var by: fx = $self_y - 4fx * spd * sin(a);
    _ = fire(TH14_BALL2, 2, bx, by, spd, a, none, none);
}

// BossCard1_at_l: two sequential SHOOT records on the same tick.
//   child 1: current angle +-15deg (0.2617994 rad), speed parent + U*1.5, parent kept (c=0)
//   child 2: alpha=0, delta=2pi -> uniform full circle, speed parent + U*1.5, parent deleted (c=1)
async sub fang_split_two() {
    wait(59);
    var r1: int = rand(65536);
    var off1: int = (r1 - 32768) * 2731 / 32768;   // 15deg = 2731 BAM
    var a1: angle = $self_angle + (off1 as angle);
    var r2: int = rand(65536);
    var u1: fx = (r2 - 32768) as fx / 65536 + 0.5fx;
    var spd1: fx = $self_speed + u1 * 1.5fx;
    var bx1: fx = $self_x - 4fx * spd1 * cos(a1);
    var by1: fx = $self_y - 4fx * spd1 * sin(a1);
    _ = fire(TH14_BALL2, 2, bx1, by1, spd1, a1, none, none);

    var r3: int = rand(65536);
    var off2: int = (r3 - 32768) * 2;              // U_signed * 360deg, full circle
    var a2: angle = off2 as angle;
    var r4: int = rand(65536);
    var u2: fx = (r4 - 32768) as fx / 65536 + 0.5fx;
    var spd2: fx = $self_speed + u2 * 1.5fx;
    var bx2: fx = $self_x - 4fx * spd2 * cos(a2);
    var by2: fx = $self_y - 4fx * spd2 * sin(a2);
    _ = fire(TH14_BALL2, 2, bx2, by2, spd2, a2, none, none);
}

// One etOn wave of at()/at_l(): fixed-direction fan (etAim mode 1) around
// FINAL_ANGLE - pi, offset 32px along each bullet's own angle (etDist 32),
// count = 1 on Easy / 3 otherwise, layers = 1, all at speed 0.
// Shared slot 0 holds the boss's current movement direction (BAM).
async sub fang_volley(iters: int, gap: int, spread: angle, count: int,
                      omega: angle, accel: fx, twin: int) {
    for n in 0..iters {
        if self_int(1) == 0 { return; }            // 2400-frame interrupt stops emissions
        var base: angle = (self_int(0) as angle) - 180deg;
        for i in 0..count {
            var a: angle = base;
            if i == 1 { a = base - spread; }
            if i == 2 { a = base + spread; }
            var bx: fx = $self_x + 32fx * cos(a);
            var by: fx = $self_y + 32fx * sin(a);
            if twin != 0 {
                _ = fire(TH14_BIG_BALL, 3, bx, by, 0fx, a, FANG_PARENT(omega, accel), fang_split_two);
            } else {
                _ = fire(TH14_BIG_BALL, 3, bx, by, 0fx, a, FANG_PARENT(omega, accel), fang_split_one);
            }
        }
        wait(gap);
    }
}

// movePosTime(frames, 4, x, y) = quadratic deceleration; FINAL_ANGLE for that move is the
// straight-line direction to the target, published for the volley task in shared slot 0.
sub boss_move(dur: int, tx: fx, ty: fx) {
    var d: angle = atan2(ty - $self_y, tx - $self_x);
    set_self_int(0, d as int);
    move_to(dur, tx, ty, EASE_QUAD_OUT);
}

async sub boss_main() {
    // Boss entry state (st03bs.ecl.txt:8-52): hit/hurt box 48x48 -> radius 24, body collision on.
    set_invuln(65535);
    set_hitbox(24fx);
    set_hurtbox(24fx);
    set_self_int(1, 1);

    // :346-358 entry move to (0,144), time 60 / 120 / 150 gates.
    // moveLimit(0,128,280,256) is reset at :356; the only motion under it stays inside the box.
    move_to(60, 0fx, 144fx, EASE_QUAD_OUT);
    wait(60);
    wait(60);
    wait(30);

    // :341-344 difficulty data, :360-361 first F0, :397-398 original A for at_l.
    var fan: int = 1;
    var iters: int = 80;
    var gap: int = 2;
    var easy_normal: int = 1;
    if global(GVAR_RANK) >= RANK_NORMAL { fan = 3; }
    if global(GVAR_RANK) > RANK_NORMAL { easy_normal = 0; }
    if global(GVAR_RANK) == RANK_HARD { iters = 60; gap = 3; }

    if easy_normal != 0 {
        // BossCard1_844..3276, Easy/Normal path: 140-frame move groups + 150/120 gaps,
        // one 550-frame cycle. 150 + 4*550 = 2350.
        for c in 0..4 {
            boss_move(40, 160fx, 256fx);                       // :366
            spawn fang_volley(50, 3, 30deg, fan, -2deg, 0.02fx, 0);   // :364 at()
            wait(40);
            boss_move(60, -160fx, 256fx);                      // :370
            wait(60);
            boss_move(40, 0fx, 128fx);                         // :374
            wait(40);
            wait(120);                                         // :402
            wait(30);                                          // :404
            boss_move(40, -160fx, 256fx);                      // :411
            spawn fang_volley(50, 3, 30deg, fan, 2deg, 0.02fx, 0);    // :408 at()
            wait(40);
            boss_move(60, 160fx, 256fx);                       // :415
            wait(60);
            boss_move(40, 0fx, 128fx);                         // :419
            wait(40);
            wait(120);                                         // :448
        }
        // Fifth cycle cut by the 2400-frame timeout, 50 frames in.
        boss_move(40, 160fx, 256fx);
        spawn fang_volley(50, 3, 30deg, fan, -2deg, 0.02fx, 0);
        wait(40);
        boss_move(60, -160fx, 256fx);
        wait(10);
    } else {
        // BossCard1_1392..2660, Hard/Lunatic path: 180-frame move groups + 150/120 gaps,
        // one 630-frame cycle. 150 + 3*630 = 2040.
        for k in 0..3 {
            boss_move(30, 160fx, 256fx);                       // :380
            spawn fang_volley(iters, gap, 45deg, fan, -2deg, 0.022fx, 1); // :378 at_l()
            wait(30);
            boss_move(40, -160fx, 192fx);                      // :384
            wait(40);
            boss_move(40, 160fx, 192fx);                       // :388
            wait(40);
            boss_move(40, -160fx, 256fx);                      // :392
            wait(40);
            boss_move(30, 0fx, 128fx);                         // :396
            wait(30);
            wait(120);                                         // :402
            wait(30);                                          // :404
            boss_move(30, -160fx, 256fx);                      // :426
            spawn fang_volley(iters, gap, 45deg, fan, 2deg, 0.022fx, 1);  // :423 at_l()
            wait(30);
            boss_move(40, 160fx, 192fx);                       // :430
            wait(40);
            boss_move(40, -160fx, 192fx);                      // :434
            wait(40);
            boss_move(40, 160fx, 256fx);                       // :438
            wait(40);
            boss_move(30, 0fx, 128fx);                         // :442
            wait(30);
            wait(120);                                         // :448
        }
        // Fourth cycle cut by the 2400-frame timeout: all 360 frames up to move 1 of volley B.
        boss_move(30, 160fx, 256fx);
        spawn fang_volley(iters, gap, 45deg, fan, -2deg, 0.022fx, 1);
        wait(30);
        boss_move(40, -160fx, 192fx);
        wait(40);
        boss_move(40, 160fx, 192fx);
        wait(40);
        boss_move(40, -160fx, 256fx);
        wait(40);
        boss_move(30, 0fx, 128fx);
        wait(30);
        wait(120);
        wait(30);
        boss_move(30, -160fx, 256fx);
        spawn fang_volley(iters, gap, 45deg, fan, 2deg, 0.022fx, 1);
        wait(30);
    }

    // Source frame 2400 = timeout -> Boss2 boundary: killAllAsync + etClear(640) + movement reset.
    set_self_int(1, 0);
    move_to(0, $self_x, $self_y, EASE_LINEAR);
    clear_bullets_at($self_x, $self_y, 640fx, 0);
    loop { wait(1); }
}

async sub pattern() {
    wait(OPENING_BUFFER);
    _ = spawn_enemy(0fx, 128fx, 1600, 0, 0, 0, boss_main);
}

async sub control() {
    set_invuln(65535);
    set_enemy_flag(ENEMY_NO_BODY, 1);
    phase_begin(0, pattern, TIME_LIMIT, 0);
    wait_spell();
    loop { wait(1); }
}

sub main() {
    _ = spawn_enemy(0fx, 0fx, 1000, 0, 0, 0, control);
    loop { wait(600); }
}

